package zombie.iso; public class IsoMovingObject extends IsoObject {public float x,y,z;public int id;public boolean dead,standing=true,prone,shootable=true; public IsoCell cell;public IsoGridSquare square=new IsoGridSquare(); public int getID(){return id;}public float getX(){return x;}public float getY(){return y;}public float getZ(){return z;} public IsoCell getCell(){return cell;}public IsoGridSquare getCurrentSquare(){return square;}public float DistToSquared(IsoMovingObject o){float dx=x-o.x,dy=y-o.y;return dx*dx+dy*dy;} public boolean isStanding(){return standing;}public boolean isProne(){return prone;}public boolean isShootable(){return shootable;}}